import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

const ACCENTS: readonly { readonly id: Accent; readonly label: string }[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

/**
 * Radio group for the app accent.
 *
 * Each swatch sets `data-accent` on itself. The swatch colour comes from
 * `var(--myelin)`, so the global stylesheet must scope the accent token to
 * `[data-accent="..."]` for the swatch to show its own accent rather than the
 * current one.
 */
export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const selectedIndex = Math.max(
    0,
    ACCENTS.findIndex((accent) => accent.id === value),
  );

  function select(index: number) {
    onChange(ACCENTS[index].id);
    buttons.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = ACCENTS.length - 1;
    let target: number;

    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        target = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        target = index === 0 ? last : index - 1;
        break;
      case "Home":
        target = 0;
        break;
      case "End":
        target = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    select(target);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {ACCENTS.map((accent, index) => {
        const checked = index === selectedIndex;
        return (
          <button
            key={accent.id}
            ref={(element) => {
              buttons.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            className="accent-picker__option"
            onClick={() => select(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span
              className="accent-picker__swatch"
              data-accent={accent.id}
              aria-hidden="true"
            />
            <span className="accent-picker__name">{accent.label}</span>
          </button>
        );
      })}
    </div>
  );
}
```

