.accent-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  border: 0;
}

.accent-picker__option {
  font: inherit;
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
  padding: 0.5em 1em 0.5em 0.6em;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font-size: clamp(0.875rem, 1.2vw, 1rem);
  line-height: 1.2;
  cursor: pointer;
  transition:
    background-color 150ms ease,
    border-color 150ms ease;
}

.accent-picker__option:hover {
  border-color: var(--ink);
}

/* Adds to the global focus outline; never replaces it. */
.accent-picker__option:focus-visible {
  border-color: var(--cresyl);
}

.accent-picker__option[aria-checked="true"] {
  border-color: var(--myelin);
  background: var(--myelin-wash);
  font-weight: 600;
}

.accent-picker__swatch {
  flex: none;
  width: 1em;
  height: 1em;
  border-radius: 50%;
  background: var(--myelin);
  transition: box-shadow 150ms ease;
}

.accent-picker__option[aria-checked="true"] .accent-picker__swatch {
  box-shadow:
    0 0 0 2px var(--slide),
    0 0 0 3px var(--myelin);
}

.accent-picker__name {
  white-space: nowrap;
}

:root[data-motion="reduce"] .accent-picker__option,
:root[data-motion="reduce"] .accent-picker__swatch {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .accent-picker__option,
  .accent-picker__swatch {
    transition: none;
  }
}
